import datetime

def run_tool(input_data):
    d1 = datetime.date.fromisoformat(input_data.get('date1', '2023-01-01'))
    d2 = datetime.date.fromisoformat(input_data.get('date2', '2024-03-15'))
    delta = d2 - d1
    days = delta.days
    years = abs(d2.year - d1.year)
    months = abs(d2.month - d1.month)
    return {'status': 'success', 'difference': {'days': days, 'months': months, 'years': years}}
